const raw = $input.item.json;
const item = raw.body || raw;
const startTime = new Date().toISOString();

let chatId = 5836961614; // Default fallback to Amir.r.s
let userName = 'User', msgText = '', hasPhoto = false, photoFileId = null, source = 'webhook';

if (item.message) {
  source = 'telegram';
  chatId = item.message.chat ? item.message.chat.id : chatId;
  userName = item.message.from ? (item.message.from.first_name || item.message.from.username) : 'User';
  msgText = (item.message.text || item.message.caption || '').trim();
  if (item.message.photo && item.message.photo.length > 0) {
    hasPhoto = true;
    photoFileId = item.message.photo[item.message.photo.length - 1].file_id;
  }
} else if (item.chat_id) {
  source = 'telegram';
  chatId = item.chat_id;
  userName = item.user_name || 'User';
  msgText = (item.message_text || item.text || '').trim();
  hasPhoto = Boolean(item.has_photo);
  photoFileId = item.photo_file_id || null;
}

let action = 'INVOICE';
const low = msgText.toLowerCase();
if (low.startsWith('/report') || low.startsWith('/stats') || low.startsWith('/list') || low.includes('گزارش')) {
  action = 'REPORT';
} else if (low.startsWith('/start') || low.startsWith('/help') || low.includes('راهنما') || (!hasPhoto && !item.mock_ai_extraction && !item.document_base64 && !low.includes('inv'))) {
  action = 'HELP';
}

return {
  json: {
    execution_start_time: startTime,
    action: action,
    source: source,
    telegram_context: { chat_id: chatId, user_name: userName, message_text: msgText, has_photo: hasPhoto, photo_file_id: photoFileId },
    filename: item.filename || (hasPhoto ? 'telegram_invoice.jpg' : 'invoice.pdf'),
    file_type: item.file_type || (hasPhoto ? 'image/jpeg' : 'application/pdf'),
    raw_extraction: item.mock_ai_extraction || null,
    received_payload: item
  }
};

