    currency: "USD",
    line_items: [
      { description: "Automated Service Unit", quantity: 2, unit_price: 150.00, total_price: 300.00 },
      { description: "Platform Fee", quantity: 1, unit_price: 50.00, total_price: 50.00 }
    ],
    subtotal: 350.00,
    tax_amount: 0.00,
    total_amount: 350.00,
