  };
}

return {
  json: {
    ...item,
    extracted_invoice: invoiceData
  }
};

const data = $input.item.json;
const inv = data.extracted_invoice;
const auditFlags = [];
let mathVerified = true;
let calculatedSubtotal = 0;

if (Array.isArray(inv.line_items) && inv.line_items.length > 0) {
  for (let i = 0; i < inv.line_items.length; i++) {
    const itm = inv.line_items[i];
    const exp = Number((itm.quantity * itm.unit_price).toFixed(2));
    if (Math.abs(exp - Number(itm.total_price)) > 0.05) {
      mathVerified = false;
      auditFlags.push(`LINE_ITEM_MISMATCH: Item #${i + 1} (${itm.description}) expected $${exp} got $${itm.total_price}`);
    }
    calculatedSubtotal += Number(itm.total_price);
  }
} else {
  auditFlags.push('NO_LINE_ITEMS_FOUND');
}

calculatedSubtotal = Number(calculatedSubtotal.toFixed(2));
if (Math.abs(calculatedSubtotal - Number(inv.subtotal)) > 0.05) {
  mathVerified = false;
  auditFlags.push(`SUBTOTAL_MISMATCH: Sum ($${calculatedSubtotal}) != subtotal ($${inv.subtotal})`);
}

const expTotal = Number((Number(inv.subtotal) + Number(inv.tax_amount || 0)).toFixed(2));
if (Math.abs(expTotal - Number(inv.total_amount)) > 0.05) {
  mathVerified = false;
  auditFlags.push(`GRAND_TOTAL_MISMATCH: Subtotal+Tax ($${expTotal}) != total ($${inv.total_amount})`);
}

if (Number(inv.total_amount) >= 2000.00) {
  auditFlags.push(`HIGH_VALUE_THRESHOLD: Total ($${inv.total_amount}) exceeds limit ($2000)`);
}

if (inv.confidence_score && inv.confidence_score < 0.85) {
  auditFlags.push(`LOW_AI_CONFIDENCE: Score (${inv.confidence_score}) < 0.85`);
}

const reqApproval = auditFlags.length > 0;
return {
  json: {
    ...data,
    validation: {
      math_verified: mathVerified,
      calculated_subtotal: calculatedSubtotal,
      audit_flags: auditFlags,
      requires_approval: reqApproval,
      status: reqApproval ? 'pending_approval' : 'auto_approved',
      validated_at: new Date().toISOString()
    }
  }
};

